<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {Download,Plus,Search} from 'lucide-vue-next';
import QueryPanel from '../components/QueryPanel.vue';import QueryField from '../components/QueryField.vue';import OperationsMap from '../components/OperationsMap.vue';import FenceEditorDrawer from '../components/FenceEditorDrawer.vue';
import {api} from '../api';import {useSessionStore} from '../stores/session';import {subjectDate,subjectError,subjectStatus,useSubjectList} from '../subject-management';import {can,exportAdmission,useAdmissionOptions,stateTone} from '../admission';import {useResponsiveDrawer} from '../province-monitoring';import {fenceTypes,monitorTime} from '../operations-supervision';import '../operations-supervision.css';
const route=useRoute(),router=useRouter(),session=useSessionStore(),user=computed(()=>session.user),width=useResponsiveDrawer(720),canWrite=computed(()=>can(user.value,'safety:fence:write'));
const {filters,rows,total,page,loading,error,search,reset,load,getFilters}=useSubjectList('/safety/fences',{enterpriseId:String(route.query.enterpriseId??''),type:'',q:String(route.query.q??'')},false);
const {options,error:optionError,load:loadOptions}=useAdmissionOptions('/safety/fences/options');
const selected=ref<any[]>([]),exporting=ref(false),drawer=ref(false),detailId=ref(''),detail=ref<any>(null),detailError=ref(''),detailLoading=ref(false),tab=ref('range'),editor=ref(false),editingId=ref('');let generation=0,triggerGeneration=0;
const triggers=ref<any[]>([]),triggerPage=ref(1),triggerTotal=ref(0),triggerError=ref(''),triggerLoading=ref(false);
const contextRegions=computed(()=>options.value.regions?.filter((r:any)=>!r.enterpriseId||r.enterpriseId===detail.value?.enterpriseId)??[]);
async function loadDetail(){triggerGeneration++;triggers.value=[];triggerTotal.value=0;const n=++generation;detail.value=null;detailLoading.value=true;detailError.value='';try{const d=await api(`/safety/fences/${detailId.value}`);if(n!==generation)return;detail.value=d;triggerPage.value=1;loadTriggers()}catch(e){if(n===generation)detailError.value=subjectError(e)}finally{if(n===generation)detailLoading.value=false}}
async function open(row:any){detailId.value=row.id;tab.value='range';drawer.value=true;await loadDetail()}
async function loadTriggers(){const n=++triggerGeneration;triggerError.value='';triggerLoading.value=true;try{const d=await api<any>(`/safety/fences/${detailId.value}/triggers?page=${triggerPage.value}&pageSize=10`);if(n===triggerGeneration){triggers.value=d.items;triggerTotal.value=d.total}}catch(e){if(n===triggerGeneration){triggers.value=[];triggerError.value=subjectError(e)}}finally{if(n===triggerGeneration)triggerLoading.value=false}}
watch(triggerPage,loadTriggers);watch(drawer,v=>{if(!v){generation++;triggerGeneration++}});onBeforeUnmount(()=>{generation++;triggerGeneration++});onMounted(()=>{if(route.query.fenceId)open({id:String(route.query.fenceId)})});
function edit(row?:any){editingId.value=row?.id??'';editor.value=true}
async function saved(row:any){editor.value=false;await load();open(row)}
async function toggle(row:any){try{await ElMessageBox.confirm(`确定${row.active?'停用':'启用'}“${row.name}”？`,'调整围栏状态',{confirmButtonText:'确认',cancelButtonText:'取消',type:'warning'});await api(`/safety/fences/${row.id}/status`,{method:'PATCH',body:JSON.stringify({active:!row.active})});ElMessage.success('围栏状态已更新');await load();if(drawer.value&&detailId.value===row.id)loadDetail()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(subjectError(e))}}
async function remove(row:any){if(row._count.triggers)return ElMessage.warning('该围栏已有触发记录，请停用并保留历史');try{await ElMessageBox.confirm(`确定删除未产生触发记录的“${row.name}”？`,'删除围栏',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'});await api(`/safety/fences/${row.id}`,{method:'DELETE'});drawer.value=false;await load();ElMessage.success('围栏已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(subjectError(e))}}
function event(id:string){router.push({path:'/safety/events',query:{view:'ALERT',eventId:id}})}
async function exportRows(){exporting.value=true;try{await exportAdmission('/safety/fences',getFilters(),[['围栏编号',r=>r.businessNo],['围栏名称',r=>r.name],['类型',r=>fenceTypes[r.fenceType]],['适用企业',r=>r.enterprise?.name??'公共规则'],['适用车辆数',r=>r.vehicles.length||'范围内全部车辆'],['生效日期',r=>subjectDate(r.validFrom)],['截止日期',r=>r.validTo?subjectDate(r.validTo):'长期'],['时段',r=>r.allowedHours],['限速',r=>r.speedLimit],['状态',r=>r.active?'已启用':'已停用'],['触发次数',r=>r._count.triggers]],'电子围栏',selected.value)}catch(e){ElMessage.error(subjectError(e))}finally{exporting.value=false}}
</script>
<template><section class="city-subject-page operations-supervision-page" :class="{'fence-inspecting':drawer}" aria-label="电子围栏">
 <QueryPanel class="subject-query subject-query--vehicles" :loading="loading" @search="search" @reset="reset"><QueryField label="关键词" keyword><el-input v-model="filters.q" clearable :prefix-icon="Search" placeholder="搜索围栏名称或编号" aria-label="搜索电子围栏"/></QueryField><QueryField label="企业"><el-select v-model="filters.enterpriseId" clearable filterable placeholder="全部企业" aria-label="围栏企业筛选"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></QueryField><QueryField label="围栏类型"><el-select v-model="filters.type" clearable placeholder="全部类型" aria-label="围栏类型筛选"><el-option v-for="key in ['NO_ENTRY','SPEED_LIMIT','TEMPORARY']" :key="key" :label="fenceTypes[key]" :value="key"/></el-select></QueryField><QueryField label="状态"><el-select v-model="filters.status" clearable placeholder="全部状态" aria-label="围栏状态筛选"><el-option label="已启用" value="ACTIVE"/><el-option label="已停用" value="INACTIVE"/></el-select></QueryField></QueryPanel>
 <section class="subject-list"><header class="subject-list-header"><h2>电子围栏 <span class="subject-count">{{total}}</span></h2><div class="subject-tools"><el-button :icon="Download" :loading="exporting" :disabled="loading||!!error" @click="exportRows">导出</el-button><el-button v-if="canWrite" type="primary" :icon="Plus" :disabled="!!optionError" @click="edit()">新建围栏</el-button></div></header>
  <div v-if="optionError" class="subject-inline-error" role="alert">围栏选项加载失败 <el-button link @click="loadOptions">重试</el-button></div><div v-if="selected.length" class="subject-bulk">已选 {{selected.length}} 项<el-button link type="primary" @click="exportRows">导出所选</el-button></div>
  <div v-if="error" class="subject-error" role="alert"><strong>围栏列表暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div>
  <div v-else class="subject-table-host"><el-table class="subject-table" v-loading="loading" :data="rows" height="100%" row-key="id" empty-text="暂无符合条件的围栏" highlight-current-row @selection-change="selected=$event"><el-table-column type="selection" width="44"/><el-table-column label="围栏名称 / 编号" :min-width="drawer?205:230"><template #default="{row}"><button class="subject-identity" :aria-label="row.name+'围栏详情'" @click="open(row)"><strong>{{row.name}}</strong><span>{{row.businessNo}}</span></button></template></el-table-column><el-table-column label="围栏类型" :min-width="drawer?105:110"><template #default="{row}"><el-tag size="small" :type="row.fenceType==='SPEED_LIMIT'?'warning':row.fenceType==='NO_ENTRY'?'danger':'info'">{{fenceTypes[row.fenceType]??row.fenceType}}</el-tag></template></el-table-column><el-table-column label="适用企业 / 车辆" :min-width="drawer?210:240"><template #default="{row}"><div class="subject-identity"><strong>{{row.enterprise?.name??'公共规则'}}</strong><span>{{row.vehicles.length?`${row.vehicles.length} 辆`:'范围内全部车辆'}}</span></div></template></el-table-column><el-table-column label="生效时间" :min-width="drawer?170:185"><template #default="{row}">{{subjectDate(row.validFrom)}} 至 {{row.validTo?subjectDate(row.validTo):'长期'}}</template></el-table-column><el-table-column label="状态" :width="drawer?95:100"><template #default="{row}"><el-tag size="small" :type="row.active?'success':'info'">{{row.active?'已启用':'已停用'}}</el-tag></template></el-table-column><el-table-column label="触发次数" :width="drawer?85:105"><template #default="{row}">{{row._count.triggers}} 次</template></el-table-column><el-table-column label="操作" :width="drawer?155:180" fixed="right"><template #default="{row}"><div class="subject-row-actions"><el-button link @click="open(row)">详情</el-button><el-button v-if="canWrite&&row.fenceType!=='OPERATION'" link @click="edit(row)">编辑</el-button><el-dropdown v-if="canWrite" trigger="click" @command="(c:string)=>c==='toggle'?toggle(row):remove(row)"><el-button link aria-label="更多围栏操作">更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="toggle" :disabled="!row.active&&row.fenceType==='OPERATION'">{{row.active?'停用':'启用'}}</el-dropdown-item><el-dropdown-item command="delete" :disabled="row._count.triggers>0">删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column></el-table></div>
  <footer class="subject-footer"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" background layout="prev,pager,next"/></footer></section>
 <el-drawer v-model="drawer" title="围栏详情" :size="width" class="subject-drawer fence-detail-drawer" :modal="false" destroy-on-close><div v-if="detailError" class="subject-error" role="alert"><strong>围栏详情加载失败</strong><span>{{detailError}}</span><el-button @click="loadDetail">重试</el-button></div><el-skeleton v-else-if="detailLoading" :rows="10"/><template v-else-if="detail"><div class="subject-detail-title"><div><h2>{{detail.name}}</h2><p>{{detail.businessNo}} · 版本 {{detail.version}}</p></div><el-tag :type="detail.active?'success':'info'">{{detail.active?'已启用':'已停用'}}</el-tag></div><el-tabs v-model="tab"><el-tab-pane label="范围与规则" name="range"><OperationsMap mode="fences" class="fence-map" :fences="[detail]" :regions="contextRegions" :selected-id="detail.id" height="350px"/><dl class="subject-detail-grid"><div><dt>围栏类型</dt><dd>{{fenceTypes[detail.fenceType]}}</dd></div><div><dt>限速值</dt><dd>{{detail.speedLimit?`${detail.speedLimit} km/h`:'不适用'}}</dd></div><div><dt>适用企业</dt><dd>{{detail.enterprise?.name??'公共规则'}}</dd></div><div><dt>适用车辆</dt><dd>{{detail.vehicles.length?`${detail.vehicles.length} 辆`:'范围内全部车辆'}}</dd></div><div><dt>生效时段</dt><dd>{{detail.allowedHours||'全天'}}</dd></div><div><dt>有效期</dt><dd>{{subjectDate(detail.validFrom)}} 至 {{detail.validTo?subjectDate(detail.validTo):'长期'}}</dd></div><div class="wide"><dt>规则说明</dt><dd>{{detail.ruleDescription||'未填写'}}</dd></div></dl><p v-if="detail.fenceType==='OPERATION'" class="fence-rule-readonly">历史运营围栏保留查询；当前运营边界以有效通行许可为准。</p><h3 class="subject-detail-section">最近触发</h3><div v-if="triggerError" role="alert">{{triggerError}}<el-button link @click="loadTriggers">重试</el-button></div><div v-else-if="triggers[0]" class="fence-event"><strong>{{triggers[0].vehicle.name}}</strong><br>{{monitorTime(triggers[0].occurredAt)}} · {{triggers[0].speed}} km/h · {{subjectStatus(triggers[0].alert.status)}}<el-button v-if="can(user,'safety:alert:read')" link type="primary" @click="event(triggers[0].alertId)">查看事件</el-button></div><p v-else class="monitor-note">暂无触发记录</p></el-tab-pane>
 <el-tab-pane :label="`触发记录（${triggerTotal}）`" name="triggers"><div v-if="triggerError" role="alert">{{triggerError}}<el-button @click="loadTriggers">重试</el-button></div><el-table v-else :data="triggers" v-loading="triggerLoading" empty-text="暂无触发记录"><el-table-column label="车辆" prop="vehicle.name"/><el-table-column label="触发时间" min-width="170"><template #default="{row}">{{monitorTime(row.occurredAt)}}</template></el-table-column><el-table-column label="速度" width="90"><template #default="{row}">{{row.speed}} km/h</template></el-table-column><el-table-column label="条件状态" width="100"><template #default="{row}">{{row.status==='RECOVERED'?'已恢复':'触发中'}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="can(user,'safety:alert:read')" link type="primary" @click="event(row.alertId)">查看事件</el-button></template></el-table-column></el-table><el-pagination v-if="triggerTotal>10" small v-model:current-page="triggerPage" :page-size="10" :total="triggerTotal" layout="prev,pager,next"/></el-tab-pane><el-tab-pane label="调整记录" name="history"><p v-if="!detail.history.length" class="monitor-note">历史围栏未登记调整版本</p><div v-for="(h,i) in [...detail.history].reverse()" :key="i" class="fence-history"><strong>{{h.summary}}</strong><br><small>{{monitorTime(h.at)}} · {{h.actor}}</small><p v-if="h.snapshot" class="monitor-note">调整前：{{h.snapshot.name}} · 版本 {{h.snapshot.version}} · {{h.snapshot.speedLimit??'—'}} km/h · {{h.snapshot.allowedHours||'全天'}}</p></div></el-tab-pane></el-tabs></template><template #footer><el-button @click="drawer=false">关闭</el-button><el-button v-if="canWrite&&detail&&detail.fenceType!=='OPERATION'" type="primary" @click="edit(detail)">编辑围栏</el-button></template></el-drawer>
 <FenceEditorDrawer v-model="editor" :fence-id="editingId" :options="options" @saved="saved"/>
</section></template>
